import { Component, onMount, Show } from "solid-js";

import { ActiveDeviceTypeChangedEventName } from "#core/ui/input/input-events.js";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { ViewExperience } from "#core/ui-next/services/view-experience.js";
import { useAspectRatio, useIsSmallScreen, useWindowSize } from "#core/ui-next/utilities/layout-utilities.js";
import { useWindowListener } from "#core/ui-next/utilities/solid-utilities.js";

import { ScreenFrame, ScreenFrameCloseHandler } from "#base/ui-next/components/screen-frame.jsx";
import { CouncilRoom } from "#base/ui-next/screens/advisor-council/advisor-screen-council-tab.jsx";
import {
	AdvisorCouncilScreenContext,
	createAdvisorCouncilScreenModel,
} from "#base/ui-next/screens/advisor-council/advisor-screen-model.js";

const AdvisorCouncilPopupComponent: Component = () => {
	const model = createAdvisorCouncilScreenModel();
	const audio = useAudio();

	const onActiveDeviceChanged = () => {
		Input.setActiveContext(InputContext.Shell);
	};

	onMount(() => {
		useWindowListener(ActiveDeviceTypeChangedEventName, onActiveDeviceChanged, true);
		if (IsControllerActive()) {
			Input.setActiveContext(InputContext.Shell);
		}
		audio("AdvisorScreen", "popup-open");
	});

	const handleOnClosing = () => {
		audio("AdvisorScreen", "popup-close");
	};

	const windowSize = useWindowSize();
	const isSmallScreen = useIsSmallScreen();
	const aspectRatio = useAspectRatio();
	const isMobile = ViewExperience() == UIViewExperience.Mobile;

	return (
		<AdvisorCouncilScreenContext.Provider value={model}>
			<ScreenFrame
				name="Advisor-Council-Popup"
				panelContext="advisor-council-popup"
				audioContext="AdvisorScreen"
				onClosing={handleOnClosing}
				ornatePanelData={model.ornatePanelData}
				title="LOC_UI_ADVISORS_CHOOSE"
				closeHandler={ScreenFrameCloseHandler.PopupSequencer}
				isFullscreen={isMobile}
			>
				<div class="w-full flex flex-col flex-auto">
					<div class={`flex-1 ${isMobile ? "mt-5" : "mt-10"} mb-8`}>
						<CouncilRoom isPopup={true} />
					</div>
					<div
						class={`text-center text-base ${IsControllerActive() && isSmallScreen() ? "mb-20" : IsControllerActive() ? "mb-24" : "mb-8"}`}
						role="note"
					>
						<L10n.Compose text={"LOC_ADVISOR_COUNCIL_NOTE"} />
					</div>
					<Show when={!IsControllerActive()}>
						<AudioContextProvider segment="Confirm">
							<Button
								class={`w-96 text-sm self-center ${isSmallScreen() ? "mb-10" : aspectRatio() <= 1.335 && windowSize() < 1080 ? "mb-32" : "mb-10"}`}
								onActivate={() => model.clickClosePopup()}
							>
								<L10n.Compose text={"LOC_ADVISOR_COUNCIL_CONFIRM"} />
							</Button>
						</AudioContextProvider>
					</Show>
				</div>
			</ScreenFrame>
		</AdvisorCouncilScreenContext.Provider>
	);
};

export const AdvisorCouncilPopup = ComponentRegistry.register({
	name: "AdvisorCouncil",
	createInstance: AdvisorCouncilPopupComponent,
});

defineLegacyComponent("advisor-council-popup", { classNames: ["fullscreen"] }, () => {
	Input.setActiveContext(InputContext.Shell);
	return <AdvisorCouncilPopupComponent />;
});
